// Generated by ../../../rebuild.py; one topology per leaf.
use rand::{Rng, rngs::StdRng};
use std::f64::consts::PI;

fn pick(rng: &mut StdRng, values: &[f64]) -> f64 {
    values[rng.random_range(0..values.len())]
}

pub fn generate(rng: &mut StdRng) -> String {
    let r = pick(rng, &[1000.0, 2200.0, 4700.0, 10000.0, 22000.0]);
    let c = pick(rng, &[1e-9, 4.7e-9, 10e-9, 47e-9, 100e-9, 1e-6]);
    let tau = r * c;
    let fc = 1.0 / (2.0 * PI * tau);
    format!(
        "RC low-pass filter\n* Ideal source; unloaded output; values in SI.\n* Time constant {tau:.5e} s; -3.0103 dB corner {fc:.5e} Hz.\nV1 in 0 DC 0 AC 1 PULSE(0 1 0 {:.5e} {:.5e} {:.5e} {:.5e})\nR1 in out {r:.5e}\nC1 out 0 {c:.5e}\n.op\n.ac dec 40 {:.5e} {:.5e}\n.tran {:.5e} {:.5e}\n.print ac vm(out) vp(out)\n.print tran v(in) v(out)\n.end",
        tau / 100.0,
        tau / 100.0,
        tau * 5.0,
        tau * 10.0,
        fc / 100.0,
        fc * 100.0,
        tau / 100.0,
        tau * 20.0
    )
}

#[cfg(test)]
mod validate;

#[cfg(test)]
mod tests {
    use super::*;
    use rand::SeedableRng;

    #[test]
    fn independent_nodal_analysis_matches_topology() {
        let mut rng = StdRng::seed_from_u64(47);
        for _ in 0..200 {
            validate::verify(&generate(&mut rng), "rc-low-pass");
        }
    }
}
